// Magazine installer. Run from the repo root or apps\web:  node install-magazine.mjs
// Old copies are saved as <name>.bak. en.json / ta.json get a new "magazine" block and 5 new "shop" keys; nothing is removed.
// Needs the Donations installer to be installed already (it extends the cart files). Uses photos already in public\images.
import fs from 'node:fs';
import path from 'node:path';
let root = process.argv[2] ? path.resolve(process.argv[2]) : process.cwd();
const isWeb = (d) => fs.existsSync(path.join(d, 'src', 'dictionaries', 'en.json'));
if (!isWeb(root) && isWeb(path.join(root, 'apps', 'web'))) root = path.join(root, 'apps', 'web');
if (!isWeb(root)) { console.error('Run this from the repo root or apps\\web.'); process.exit(1); }
console.log('Installing into ' + root + '\n');
const FILES = {"src/data/magazine.ts":"// DUMMY DATA. The CMS portal will replace this file: keep the shape, swap the source.\n// Plans and prices are from the old website's Magazine page (Annual Rs. 600, Two Year Rs. 1200, Five Year Rs. 3000).\n// The old page does not say how many issues a plan has; \"monthly\" and 12 issues a year are assumed until the ashram confirms.\n// The issues in the digital archive are placeholders from the design reference, not the real back issues.\n\nimport type { L } from './sevas';\n\nexport type Plan = {\n  slug: string;\n  years: number;\n  price: number;           // rupees for the whole plan\n  name: L;\n  featured?: boolean;\n};\n\nexport const ISSUES_PER_YEAR = 12;\n\nexport const PLANS: Plan[] = [\n  { slug: 'magazine-1-year', years: 1, price: 600, name: { en: '1-Year Membership', ta: '1 ஆண்டு உறுப்பினர்' } },\n  { slug: 'magazine-2-year', years: 2, price: 1200, name: { en: '2-Year Membership', ta: '2 ஆண்டு உறுப்பினர்' } },\n  { slug: 'magazine-5-year', years: 5, price: 3000, name: { en: '5-Year Membership', ta: '5 ஆண்டு உறுப்பினர்' }, featured: true },\n];\n\nexport const getPlan = (slug: string) => PLANS.find((p) => p.slug === slug);\n\nexport type Issue = {\n  id: string;\n  year: number;\n  month: number;           // 1-12\n  title: L;\n  desc: L;\n  cover: string;           // picture in /public/images\n  pdf: string;             // '' until the file is uploaded (put it in /public/magazine/)\n  readUrl: string;         // '' until an online reader link exists\n};\n\nexport const ISSUES: Issue[] = [\n  { id: '2026-01', year: 2026, month: 1, cover: '/images/ashram-vidyapitham.jpg', pdf: '', readUrl: '',\n    title: { en: 'Mandukya Upanishad Rahasyam', ta: 'மாண்டூக்ய உபநிஷத ரகசியம்' },\n    desc: { en: 'Understanding the state of Turiya and the deep significance of Pranava Pranayama.', ta: 'துரீய நிலையும் பிரணவ பிராணாயாமத்தின் ஆழ்ந்த பொருளும்.' } },\n  { id: '2025-12', year: 2025, month: 12, cover: '/images/ashram-patashala.jpg', pdf: '', readUrl: '',\n    title: { en: 'Thayumanavar Siddhantha Deepam', ta: 'தாயுமானவர் சித்தாந்த தீபம்' },\n    desc: { en: 'Exploring non-dualistic devotional hymns and paths of mental tranquility.', ta: 'அத்வைத பக்திப் பாடல்களும் மன அமைதிக்கான வழிகளும்.' } },\n  { id: '2025-11', year: 2025, month: 11, cover: '/images/festival.jpg', pdf: '', readUrl: '',\n    title: { en: 'The Essence of Gita Chapter 12', ta: 'கீதை 12-ஆம் அத்தியாயத்தின் சாரம்' },\n    desc: { en: 'Sadhana practices of a true devotee as expounded by Swamiji.', ta: 'ஸ்வாமிஜி விளக்கியபடி உண்மையான பக்தனின் சாதனைப் பயிற்சிகள்.' } },\n  { id: '2025-10', year: 2025, month: 10, cover: '/images/ashram-classroom.jpg', pdf: '', readUrl: '',\n    title: { en: 'Thirukkural and Vedanta', ta: 'திருக்குறளும் வேதாந்தமும்' },\n    desc: { en: 'How the Kural points to the same truths as the Upanishads.', ta: 'உபநிஷதங்கள் கூறும் உண்மைகளையே குறள் எவ்வாறு சுட்டுகிறது.' } },\n  { id: '2024-12', year: 2024, month: 12, cover: '/images/ashram-river.jpg', pdf: '', readUrl: '',\n    title: { en: 'Guru Puja and the Guru Tradition', ta: 'குரு பூஜையும் குரு பரம்பரையும்' },\n    desc: { en: 'The meaning of Guru Puja and the lineage of the ashram.', ta: 'குரு பூஜையின் பொருளும் ஆசிரமத்தின் குரு பரம்பரையும்.' } },\n  { id: '2024-06', year: 2024, month: 6, cover: '/images/ashram-vilasa.jpg', pdf: '', readUrl: '',\n    title: { en: 'Daily Sadhana for Householders', ta: 'இல்லறத்தாருக்கான தினசரி சாதனை' },\n    desc: { en: 'A simple daily routine of prayer, study and service.', ta: 'பிரார்த்தனை, படிப்பு, சேவை அடங்கிய எளிய தினசரி வழக்கம்.' } },\n  { id: '2023-03', year: 2023, month: 3, cover: '/images/ashram-dining.jpg', pdf: '', readUrl: '',\n    title: { en: 'Annadhanam: Feeding as Worship', ta: 'அன்னதானம்: உணவளித்தலே வழிபாடு' },\n    desc: { en: 'Why feeding others is held as a form of worship.', ta: 'பிறருக்கு உணவளிப்பது ஏன் வழிபாடாகக் கருதப்படுகிறது.' } },\n  { id: '2022-08', year: 2022, month: 8, cover: '/images/ashram-ghosala.jpg', pdf: '', readUrl: '',\n    title: { en: 'Care of the Cow', ta: 'பசு பராமரிப்பு' },\n    desc: { en: 'The place of the cow in the ashram and in tradition.', ta: 'ஆசிரமத்திலும் மரபிலும் பசுவின் இடம்.' } },\n];\n\nexport const MONTHS_LONG: Record<'en' | 'ta', string[]> = {\n  en: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'],\n  ta: ['ஜனவரி', 'பிப்ரவரி', 'மார்ச்', 'ஏப்ரல்', 'மே', 'ஜூன்', 'ஜூலை', 'ஆகஸ்ட்', 'செப்டம்பர்', 'அக்டோபர்', 'நவம்பர்', 'டிசம்பர்'],\n};\n","src/lib/cartItem.ts":"import type { Locale } from './i18n';\nimport { getSeva, txt } from '@/data/sevas';\nimport { getDonation } from '@/data/donations';\nimport { getPlan } from '@/data/magazine';\n\n// The cart holds two kinds of lines: sevas and donations. Each has its own payment gateway later.\nexport type Stream = 'seva' | 'donation';\nexport const STREAMS: Stream[] = ['seva', 'donation'];\nexport const parseStream = (v: string | string[] | undefined): Stream => (v === 'donation' ? 'donation' : 'seva');\n\n// Lines saved before donations existed have no stream, so they are sevas\nexport const streamOf = (l: { stream?: Stream }): Stream => l.stream ?? 'seva';\n\nexport type ItemInfo = {\n  name: string;\n  href: string;          // detail page\n  photo: string;         // CSS background-image\n  fixedPrice: boolean;   // false = the buyer chose the amount\n  maxQty: number;\n  party: 'devotee' | 'donor' | 'subscriber';   // what the name on the line is called\n};\n\nconst FALLBACK = 'linear-gradient(135deg, #7A1C1C 0%, #D97706 140%)';\n\nexport function itemInfo(stream: Stream, slug: string, locale: Locale): ItemInfo {\n  if (stream === 'donation') {\n    // Magazine subscriptions are paid like donations (the old site calls them \"Subscription Donation\")\n    const plan = getPlan(slug);\n    if (plan) return { name: txt(plan.name, locale), href: `/${locale}/magazine`, photo: FALLBACK, fixedPrice: true, maxQty: 1, party: 'subscriber' };\n    const d = getDonation(slug);\n    return {\n      name: d ? txt(d.name, locale) : slug,\n      href: `/${locale}/donate/${slug}`,\n      photo: FALLBACK,\n      fixedPrice: d ? d.amount > 0 : false,\n      maxQty: d?.maxQty ?? 10,\n      party: 'donor',\n    };\n  }\n  const s = getSeva(slug);\n  return {\n    name: s ? txt(s.name, locale) : slug,\n    href: `/${locale}/sevas/${slug}`,\n    photo: `url('/images/sevas/${slug}.jpg'), ${FALLBACK}`,\n    fixedPrice: s ? s.amount > 0 : false,\n    maxQty: s?.maxQty ?? 10,\n    party: 'devotee',\n  };\n}\n","src/components/cart/CartProvider.tsx":"'use client';\n\n// The cart lives in the browser (localStorage) while the site is UI-only.\n// When the backend is ready, replace the read/write calls below with API calls.\n\nimport type { FamilyMember } from '@/data/sankalpam';\nimport { streamOf, type Stream } from '@/lib/cartItem';\nimport { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';\n\nexport type Shipping = { phone: string; address: string; district: string; pin: string; renew: boolean };\n\nexport type CartLine = {\n  id: string;\n  stream?: Stream;    // 'seva' (default, also for lines saved earlier) or 'donation'\n  slug: string;\n  qty: number;\n  unit: number;       // amount for one, in rupees\n  date: string;       // YYYY-MM-DD (empty for donations)\n  devotee: string;    // devotee name for a seva, donor name for a donation\n  gotram: string;\n  nakshatram: string;\n  rasi?: string;                 // moon sign (optional, added with the sankalpam form)\n  family?: FamilyMember[];       // family members named in the sankalpam\n  ship?: Shipping;               // delivery address, for magazine subscriptions\n};\n\nexport type Contact = { name: string; phone: string; email: string; address: string; city: string; state: string; pin: string; country: string };\nexport const EMPTY_CONTACT: Contact = { name: '', phone: '', email: '', address: '', city: '', state: '', pin: '', country: 'India' };\n\nexport type Order = { id: string; stream: Stream; placedAt: string; lines: CartLine[]; total: number; contact: Contact; method: string };\n\nconst KEY_CART = 'vedaneri.cart.v1';\nconst KEY_CONTACT = 'vedaneri.contact.v1';\nconst KEY_ORDER = 'vedaneri.order.v1';\n\n// Browser storage can be blocked or empty (private windows), so every call is wrapped.\nfunction read<T>(key: string, fallback: T): T {\n  try {\n    const raw = window.localStorage.getItem(key);\n    return raw ? (JSON.parse(raw) as T) : fallback;\n  } catch {\n    return fallback;\n  }\n}\nfunction write(key: string, value: unknown) {\n  try {\n    window.localStorage.setItem(key, JSON.stringify(value));\n  } catch {\n    /* ignore */\n  }\n}\n\ntype CartContextValue = {\n  ready: boolean;                 // false until the saved cart has been read\n  lines: CartLine[];\n  count: number;                  // number of items in the whole cart (quantities added up)\n  total: number;                  // all lines together\n  linesOf: (stream: Stream) => CartLine[];\n  totalOf: (stream: Stream) => number;\n  add: (line: Omit<CartLine, 'id'>) => void;\n  setQty: (id: string, qty: number) => void;\n  remove: (id: string) => void;\n  contact: Contact;\n  saveContact: (c: Contact) => void;\n  order: Order | null;            // the last paid order\n  placeOrder: (method: string, stream: Stream) => Order | null;  // pays one section only\n};\n\nconst CartContext = createContext<CartContextValue | null>(null);\n\nexport function useCart() {\n  const ctx = useContext(CartContext);\n  if (!ctx) throw new Error('useCart must be used inside <CartProvider>');\n  return ctx;\n}\n\nexport default function CartProvider({ children }: { children: ReactNode }) {\n  const [ready, setReady] = useState(false);\n  const [lines, setLines] = useState<CartLine[]>([]);\n  const [contact, setContact] = useState<Contact>(EMPTY_CONTACT);\n  const [order, setOrder] = useState<Order | null>(null);\n\n  useEffect(() => {\n    setLines(read<CartLine[]>(KEY_CART, []));\n    setContact({ ...EMPTY_CONTACT, ...read<Partial<Contact>>(KEY_CONTACT, {}) });\n    setOrder(read<Order | null>(KEY_ORDER, null));\n    setReady(true);\n  }, []);\n\n  useEffect(() => {\n    if (!ready) return;\n    write(KEY_CART, lines);\n    write(KEY_CONTACT, contact);\n    write(KEY_ORDER, order);\n  }, [ready, lines, contact, order]);\n\n  const add = useCallback((line: Omit<CartLine, 'id'>) => {\n    const id = `${line.slug}-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;\n    setLines((l) => [...l, { ...line, id }]);\n  }, []);\n\n  const setQty = useCallback((id: string, qty: number) => {\n    setLines((l) => l.map((x) => (x.id === id ? { ...x, qty } : x)));\n  }, []);\n\n  const remove = useCallback((id: string) => setLines((l) => l.filter((x) => x.id !== id)), []);\n\n  const saveContact = useCallback((c: Contact) => setContact(c), []);\n\n  const total = useMemo(() => lines.reduce((s, l) => s + l.unit * l.qty, 0), [lines]);\n  const count = useMemo(() => lines.reduce((s, l) => s + l.qty, 0), [lines]);\n\n  const linesOf = useCallback((stream: Stream) => lines.filter((l) => streamOf(l) === stream), [lines]);\n  const totalOf = useCallback((stream: Stream) => linesOf(stream).reduce((s, l) => s + l.unit * l.qty, 0), [linesOf]);\n\n  // Pays one section (sevas or donations); the other section stays in the cart\n  const placeOrder = useCallback(\n    (method: string, stream: Stream) => {\n      const mine = lines.filter((l) => streamOf(l) === stream);\n      if (mine.length === 0) return null;\n      const d = new Date();\n      const stamp = `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;\n      const o: Order = {\n        id: `VN-${stream === 'donation' ? 'D' : 'S'}-${stamp}-${Math.floor(1000 + Math.random() * 9000)}`,\n        stream,\n        placedAt: d.toISOString(),\n        lines: mine,\n        total: mine.reduce((s, l) => s + l.unit * l.qty, 0),\n        contact,\n        method,\n      };\n      setOrder(o);\n      setLines((all) => all.filter((l) => streamOf(l) !== stream));\n      return o;\n    },\n    [lines, contact],\n  );\n\n  const value = useMemo<CartContextValue>(\n    () => ({ ready, lines, count, total, linesOf, totalOf, add, setQty, remove, contact, saveContact, order, placeOrder }),\n    [ready, lines, count, total, linesOf, totalOf, add, setQty, remove, contact, saveContact, order, placeOrder],\n  );\n\n  return <CartContext.Provider value={value}>{children}</CartContext.Provider>;\n}\n","src/components/cart/CartView.tsx":"'use client';\n\nimport Link from 'next/link';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { formatDate, rupees } from '@/lib/format';\nimport { itemInfo, type Stream } from '@/lib/cartItem';\nimport { GOTRAMS, NAKSHATRAMS, RASIS, RELATIONS, labelFor } from '@/data/sankalpam';\nimport { useCart } from './CartProvider';\n\n// One cart, two sections. Sevas and donations are paid separately (each has its own payment gateway).\nexport default function CartView({ t, locale }: { t: Dictionary['shop']; locale: Locale }) {\n  const { ready, lines, linesOf, totalOf, setQty, remove } = useCart();\n  const href = (p: string) => `/${locale}${p}`;\n\n  if (!ready) return <p role=\"status\" className=\"py-16 text-center text-charcoal/70\">{t.loading}</p>;\n\n  if (lines.length === 0) {\n    return (\n      <div className=\"mx-auto max-w-xl rounded-2xl bg-rose/50 px-6 py-14 text-center\">\n        <p className=\"font-display text-3xl font-semibold text-maroon\">{t.cartEmpty}</p>\n        <p className=\"mt-2 font-serif text-lg text-charcoal/90\">{t.cartEmptyText}</p>\n        <div className=\"mt-6 flex flex-col justify-center gap-3 sm:flex-row\">\n          <Link href={href('/sevas')} className=\"rounded-md bg-maroon px-7 py-3 font-semibold text-white hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.browse}</Link>\n          <Link href={href('/donate')} className=\"rounded-md border-2 border-maroon px-7 py-3 font-semibold text-maroon hover:bg-rose focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.browseDonations}</Link>\n        </div>\n      </div>\n    );\n  }\n\n  const sections: { stream: Stream; title: string; checkout: string; more: string; moreHref: string }[] = [\n    { stream: 'seva', title: t.sectionSeva, checkout: t.checkoutSeva, more: t.continueShopping, moreHref: href('/sevas') },\n    { stream: 'donation', title: t.sectionDonation, checkout: t.checkoutDonation, more: t.continueDonations, moreHref: href('/donate') },\n  ];\n\n  return (\n    <div className=\"space-y-12\">\n      {sections.map(({ stream, title, checkout, more, moreHref }) => {\n        const items = linesOf(stream);\n        if (items.length === 0) return null;\n        const count = items.reduce((s, l) => s + l.qty, 0);\n        const total = totalOf(stream);\n        return (\n          <section key={stream} aria-labelledby={`cart-${stream}`}>\n            <h2 id={`cart-${stream}`} className=\"font-display text-3xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.35] [html[lang='ta']_&]:text-2xl\">\n              {title} <span className=\"text-xl text-charcoal/60\">({count})</span>\n            </h2>\n            <div aria-hidden=\"true\" className=\"mb-5 mt-2 flex items-center gap-3\"><span className=\"h-px w-12 bg-saffron\" /><span className=\"h-2 w-2 rotate-45 bg-saffron\" /><span className=\"h-px w-12 bg-saffron\" /></div>\n\n            <div className=\"flex flex-col items-start gap-8 lg:flex-row\">\n              <ul className=\"w-full min-w-0 flex-1 space-y-4\">\n                {items.map((l) => {\n                  const info = itemInfo(stream, l.slug, locale);\n                  return (\n                    <li key={l.id} className=\"flex flex-col gap-4 rounded-2xl bg-white p-4 shadow-md ring-1 ring-rose sm:flex-row sm:p-5\">\n                      {stream === 'seva' && (\n                        <div role=\"img\" aria-label={info.name} className=\"h-32 w-full shrink-0 rounded-xl bg-maroon bg-cover bg-center sm:h-28 sm:w-36\" style={{ backgroundImage: info.photo }} />\n                      )}\n                      <div className=\"flex min-w-0 flex-1 flex-col\">\n                        <h3 className=\"font-display text-2xl font-semibold leading-tight text-maroon [html[lang='ta']_&]:!leading-[1.4] [html[lang='ta']_&]:text-xl\">\n                          <Link href={info.href} className=\"hover:underline\">{info.name}</Link>\n                        </h3>\n                        <dl className=\"mt-2 grid gap-x-6 gap-y-1 text-sm sm:grid-cols-2\">\n                          {l.date && <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.dateLabel}:</dt><dd>{formatDate(l.date, locale)}</dd></div>}\n                          <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{info.party === 'subscriber' ? t.subscriberLabel : info.party === 'donor' ? t.donorLabel : t.devoteeLabel}:</dt><dd>{l.devotee}</dd></div>\n                          {l.ship && <div className=\"flex gap-2 sm:col-span-2\"><dt className=\"font-bold text-charcoal/70\">{t.shipLabel}:</dt><dd>{l.ship.address}, {l.ship.district} - {l.ship.pin} · {l.ship.phone} · {t.renewLabel}: {l.ship.renew ? t.yes : t.no}</dd></div>}\n                          {l.gotram && <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.gotramLabel}:</dt><dd>{labelFor(GOTRAMS, l.gotram, locale)}</dd></div>}\n                          {l.rasi && <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.rasiLabel}:</dt><dd>{labelFor(RASIS, l.rasi, locale)}</dd></div>}\n                          {l.nakshatram && <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.nakshatramLabel}:</dt><dd>{labelFor(NAKSHATRAMS, l.nakshatram, locale)}</dd></div>}\n                          {l.family && l.family.length > 0 && (\n                            <div className=\"flex gap-2 sm:col-span-2\"><dt className=\"font-bold text-charcoal/70\">{t.familyLabel}:</dt><dd>{l.family.map((m) => (m.relation ? `${m.name} (${labelFor(RELATIONS, m.relation, locale)})` : m.name)).join(', ')}</dd></div>\n                          )}\n                        </dl>\n\n                        <div className=\"mt-4 flex flex-wrap items-center justify-between gap-3\">\n                          {info.fixedPrice && info.maxQty <= 1 ? (\n                            <span className=\"text-sm text-charcoal/70\">{t.qtyLabel}: 1</span>\n                          ) : info.fixedPrice ? (\n                            <div className=\"inline-flex items-center rounded-md border-2 border-rose\" role=\"group\" aria-label={t.qtyLabel}>\n                              <button type=\"button\" aria-label={t.decrease} disabled={l.qty <= 1} onClick={() => setQty(l.id, l.qty - 1)} className=\"h-10 w-10 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">−</button>\n                              <span aria-live=\"polite\" className=\"w-10 text-center font-bold\">{l.qty}</span>\n                              <button type=\"button\" aria-label={t.increase} disabled={l.qty >= info.maxQty} onClick={() => setQty(l.id, l.qty + 1)} className=\"h-10 w-10 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">+</button>\n                            </div>\n                          ) : (\n                            <span className=\"text-sm text-charcoal/70\">{t.yourAmount}</span>\n                          )}\n                          <p className=\"font-display text-3xl font-semibold text-charcoal\">{rupees(l.qty * l.unit)}</p>\n                        </div>\n                        <button type=\"button\" onClick={() => remove(l.id)} className=\"mt-3 self-start text-sm font-semibold text-maroon underline underline-offset-4 hover:text-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-saffron\">{t.remove}</button>\n                      </div>\n                    </li>\n                  );\n                })}\n              </ul>\n\n              <aside aria-label={`${t.summaryTitle}: ${title}`} className=\"w-full rounded-2xl bg-white p-6 shadow-lg ring-2 ring-rose lg:sticky lg:top-24 lg:w-80 lg:shrink-0\">\n                <h3 className=\"font-display text-2xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.4]\">{t.summaryTitle}</h3>\n                <dl className=\"mt-4 space-y-2\">\n                  <div className=\"flex justify-between\"><dt className=\"text-charcoal/80\">{title}</dt><dd className=\"font-semibold\">{count}</dd></div>\n                  <div className=\"flex items-baseline justify-between border-t-2 border-rose pt-4\">\n                    <dt className=\"font-bold\">{t.total}</dt>\n                    <dd className=\"font-display text-3xl font-semibold text-maroon\">{rupees(total)}</dd>\n                  </div>\n                </dl>\n                <Link href={href(`/checkout?stream=${stream}`)} className=\"mt-6 block rounded-md bg-maroon px-5 py-3 text-center font-semibold text-white transition-colors hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{checkout}</Link>\n                <Link href={moreHref} className=\"mt-3 block text-center text-sm font-semibold text-maroon underline underline-offset-4\">{more}</Link>\n                <p className=\"mt-4 text-center text-xs text-charcoal/70\">{t.receiptNote}</p>\n              </aside>\n            </div>\n          </section>\n        );\n      })}\n      {linesOf('seva').length > 0 && linesOf('donation').length > 0 && (\n        <p className=\"rounded-xl bg-saffron/15 px-4 py-3 text-center text-sm font-semibold text-charcoal\">{t.twoPaymentsNote}</p>\n      )}\n    </div>\n  );\n}\n","src/components/cart/ConfirmationView.tsx":"'use client';\n\nimport Link from 'next/link';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { formatDate, rupees } from '@/lib/format';\nimport { itemInfo, streamOf } from '@/lib/cartItem';\nimport { GOTRAMS, NAKSHATRAMS, RASIS, RELATIONS, labelFor } from '@/data/sankalpam';\nimport { useCart } from './CartProvider';\n\nexport default function ConfirmationView({ t, locale }: { t: Dictionary['shop']; locale: Locale }) {\n  const { ready, order } = useCart();\n  const href = (p: string) => `/${locale}${p}`;\n\n  if (!ready) return <p role=\"status\" className=\"py-16 text-center text-charcoal/70\">{t.loading}</p>;\n\n  if (!order) {\n    return (\n      <div className=\"mx-auto max-w-xl rounded-2xl bg-rose/50 px-6 py-14 text-center\">\n        <p className=\"font-serif text-lg text-charcoal\">{t.noOrder}</p>\n        <Link href={href('/sevas')} className=\"mt-6 inline-block rounded-md bg-maroon px-7 py-3 font-semibold text-white hover:bg-charcoal\">{t.browse}</Link>\n      </div>\n    );\n  }\n\n  const stream = streamOf(order);\n  const isDonation = stream === 'donation';\n  const method = t.methods.find((m) => m.key === order.method)?.label ?? order.method;\n  const placed = order.placedAt.slice(0, 10);\n\n  return (\n    <div className=\"mx-auto max-w-3xl\">\n      <div className=\"rounded-2xl bg-white p-6 shadow-lg ring-2 ring-saffron sm:p-10\">\n        <div className=\"text-center\">\n          <span aria-hidden=\"true\" className=\"mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-saffron text-3xl font-bold text-charcoal\">✓</span>\n          <h2 className=\"mt-4 font-display text-4xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-3xl\">{isDonation ? t.confirmTitleDonation : t.confirmTitle}</h2>\n          <p className=\"mx-auto mt-2 max-w-xl font-serif text-lg text-charcoal/90\">{isDonation ? t.confirmTextDonation : t.confirmText}</p>\n          <p className=\"mt-2 text-sm font-semibold text-charcoal/70\">{t.receiptSent.replace('{email}', order.contact.email)}</p>\n        </div>\n\n        <dl className=\"mt-8 grid gap-4 rounded-xl bg-rose/50 p-5 sm:grid-cols-3\">\n          <div><dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.orderId}</dt><dd className=\"mt-1 font-bold text-charcoal\">{order.id}</dd></div>\n          <div><dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.orderDate}</dt><dd className=\"mt-1 font-bold text-charcoal\">{formatDate(placed, locale)}</dd></div>\n          <div><dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.paidWith}</dt><dd className=\"mt-1 font-bold text-charcoal\">{method}</dd></div>\n        </dl>\n\n        <h3 className=\"mt-8 font-display text-2xl font-semibold text-maroon\">{isDonation ? t.yourDonations : t.yourSevas}</h3>\n        <ul className=\"mt-2 divide-y divide-rose\">\n          {order.lines.map((l) => {\n            const info = itemInfo(stream, l.slug, locale);\n            return (\n              <li key={l.id} className=\"flex items-start justify-between gap-4 py-3\">\n                <div>\n                  <p className=\"font-semibold text-charcoal\">{info.name}</p>\n                  <p className=\"text-sm text-charcoal/70\">{l.date ? `${formatDate(l.date, locale)} · ` : ''}{l.devotee}{l.gotram ? ` · ${labelFor(GOTRAMS, l.gotram, locale)}` : ''}{l.rasi ? ` · ${labelFor(RASIS, l.rasi, locale)}` : ''}{l.nakshatram ? ` · ${labelFor(NAKSHATRAMS, l.nakshatram, locale)}` : ''}</p>\n                  {l.ship && <p className=\"text-sm text-charcoal/70\">{t.shipLabel}: {l.ship.address}, {l.ship.district} - {l.ship.pin} · {l.ship.phone}</p>}\n                  {l.family && l.family.length > 0 && (\n                    <p className=\"text-sm text-charcoal/70\">{t.familyLabel}: {l.family.map((m) => (m.relation ? `${m.name} (${labelFor(RELATIONS, m.relation, locale)})` : m.name)).join(', ')}</p>\n                  )}\n                  <p className=\"text-sm text-charcoal/70\">{l.qty} × {rupees(l.unit)}</p>\n                </div>\n                <p className=\"shrink-0 font-bold\">{rupees(l.qty * l.unit)}</p>\n              </li>\n            );\n          })}\n        </ul>\n        <p className=\"mt-2 flex items-baseline justify-between border-t-2 border-rose pt-4\">\n          <span className=\"font-bold\">{t.total}</span>\n          <span className=\"font-display text-3xl font-semibold text-maroon\">{rupees(order.total)}</span>\n        </p>\n\n        <div className=\"mt-8 flex flex-col gap-3 sm:flex-row sm:justify-center\">\n          <Link href={href(isDonation ? '/donate' : '/sevas')} className=\"rounded-md bg-maroon px-7 py-3 text-center font-semibold text-white hover:bg-charcoal\">{isDonation ? t.moreDonations : t.moreSevas}</Link>\n          <Link href={href('/cart')} className=\"rounded-md border-2 border-maroon px-7 py-3 text-center font-semibold text-maroon hover:bg-rose\">{t.backToCart}</Link>\n          <Link href={href('')} className=\"rounded-md border-2 border-maroon px-7 py-3 text-center font-semibold text-maroon hover:bg-rose\">{t.backHome}</Link>\n        </div>\n      </div>\n    </div>\n  );\n}\n","src/components/magazine/SubscribeSection.tsx":"'use client';\n\nimport Link from 'next/link';\nimport { useRouter } from 'next/navigation';\nimport { useEffect, useRef, useState } from 'react';\nimport { useCart } from '@/components/cart/CartProvider';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { rupees } from '@/lib/format';\nimport { txt } from '@/data/sevas';\nimport { ISSUES_PER_YEAR, PLANS, getPlan } from '@/data/magazine';\n\ntype T = Dictionary['magazine'];\ntype Form = { name: string; phone: string; address: string; district: string; pin: string; renew: boolean };\nconst EMPTY: Form = { name: '', phone: '', address: '', district: '', pin: '', renew: false };\n\nconst inputClass = 'w-full rounded-md border-2 border-rose bg-white px-3 py-2.5 text-charcoal placeholder:text-charcoal/50 focus:border-saffron focus:outline-none';\nconst btnPrimary = 'inline-flex w-full items-center justify-center rounded-md bg-maroon px-6 py-3 font-semibold text-white transition-colors hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-maroon';\nconst btnGhost = 'inline-flex w-full items-center justify-center rounded-md border-2 border-maroon px-6 py-3 font-semibold text-maroon transition-colors hover:bg-maroon hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-maroon';\n\n// Plan cards, the shipping form and \"add to cart\". DEMO: the cart is stored in this browser; the backend will take over later.\nexport default function SubscribeSection({ locale, t }: { locale: Locale; t: T }) {\n  const router = useRouter();\n  const { add, contact } = useCart();\n  const [slug, setSlug] = useState('magazine-5-year');\n  const [f, setF] = useState<Form>(EMPTY);\n  const [errors, setErrors] = useState<Record<string, string>>({});\n  const [added, setAdded] = useState(false);\n  const doneRef = useRef<HTMLDivElement>(null);\n\n  useEffect(() => {\n    setF((x) => ({ ...x, name: x.name || contact.name, phone: x.phone || contact.phone }));\n  }, [contact.name, contact.phone]);\n\n  useEffect(() => {\n    if (added) doneRef.current?.focus();\n  }, [added]);\n\n  const plan = getPlan(slug);\n  const set = (k: keyof Form) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {\n    setF((x) => ({ ...x, [k]: e.target.type === 'checkbox' ? (e.target as HTMLInputElement).checked : e.target.value }));\n    if (errors[k]) setErrors((x) => ({ ...x, [k]: '' }));\n  };\n\n  function submit(go: boolean) {\n    const er: Record<string, string> = {};\n    if (!plan) er.plan = t.errPlan;\n    if (!f.name.trim()) er.name = t.errName;\n    if (!/^\\d{10}$/.test(f.phone.replace(/[\\s-]/g, '').replace(/^(\\+91|0)/, ''))) er.phone = t.errPhone;\n    if (!f.address.trim()) er.address = t.errAddress;\n    if (!f.district.trim()) er.district = t.errDistrict;\n    if (!/^\\d{6}$/.test(f.pin.trim())) er.pin = t.errPin;\n    setErrors(er);\n    if (Object.keys(er).length || !plan) return;\n    add({\n      stream: 'donation', slug: plan.slug, qty: 1, unit: plan.price, date: '', devotee: f.name.trim(), gotram: '', nakshatram: '',\n      ship: { phone: f.phone.trim(), address: f.address.trim(), district: f.district.trim(), pin: f.pin.trim(), renew: f.renew },\n    });\n    if (go) {\n      router.push(`/${locale}/cart?stream=donation`);\n      return;\n    }\n    setAdded(true);\n  }\n\n  return (\n    <div>\n      <div className=\"text-center\">\n        <h2 className=\"font-display text-3xl font-semibold text-maroon sm:text-4xl [html[lang='ta']_&]:!leading-[1.3]\">{t.plansTitle}</h2>\n        <div aria-hidden=\"true\" className=\"mt-3 flex items-center justify-center gap-3\"><span className=\"h-px w-12 bg-saffron\" /><span className=\"h-2 w-2 rotate-45 bg-saffron\" /><span className=\"h-px w-12 bg-saffron\" /></div>\n        <p className=\"mt-3 text-charcoal/80\">{t.plansText}</p>\n      </div>\n\n      <div role=\"radiogroup\" aria-label={t.plansTitle} className=\"mt-8 grid gap-5 md:grid-cols-3\">\n        {PLANS.map((p) => {\n          const on = p.slug === slug;\n          const issues = p.years * ISSUES_PER_YEAR;\n          return (\n            <button\n              key={p.slug}\n              type=\"button\"\n              role=\"radio\"\n              aria-checked={on}\n              onClick={() => { setSlug(p.slug); setAdded(false); if (errors.plan) setErrors((x) => ({ ...x, plan: '' })); }}\n              className={`relative flex flex-col rounded-2xl p-6 text-left transition focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron ${on ? 'bg-maroon text-white shadow-xl ring-4 ring-saffron' : 'bg-white text-charcoal shadow ring-1 ring-rose hover:shadow-lg'}`}\n            >\n              {p.featured && <span className=\"absolute -top-3 right-5 rounded-full bg-saffron px-3 py-0.5 text-xs font-bold uppercase tracking-wider text-charcoal [html[lang='ta']_&]:tracking-normal\">{t.bestValue}</span>}\n              <span className={`font-display text-2xl font-semibold ${on ? 'text-white' : 'text-maroon'}`}>{txt(p.name, locale)}</span>\n              <span className=\"mt-3 font-display text-5xl font-semibold\">{rupees(p.price)}</span>\n              <span className={`mt-1 text-sm ${on ? 'text-white/80' : 'text-charcoal/70'}`}>{t.perPlan}</span>\n              <span className={`mt-4 border-t pt-3 text-sm ${on ? 'border-white/30' : 'border-rose'}`}>\n                <strong>{issues}</strong> {t.issues} · {t.perIssue.replace('{n}', rupees(Math.round(p.price / issues)))}\n              </span>\n              <span className={`mt-4 inline-flex items-center justify-center rounded-md px-4 py-2 text-sm font-semibold ${on ? 'bg-saffron text-charcoal' : 'border-2 border-maroon text-maroon'}`}>{on ? `✓ ${t.selected}` : t.choose}</span>\n            </button>\n          );\n        })}\n      </div>\n      {errors.plan && <p role=\"alert\" className=\"mt-3 text-center text-sm font-semibold text-maroon\">{errors.plan}</p>}\n      <p className=\"mt-4 text-center text-sm text-charcoal/70\">{t.planNote}</p>\n\n      <section id=\"subscribe-form\" aria-labelledby=\"ship-title\" className=\"mx-auto mt-10 max-w-3xl rounded-2xl bg-white p-6 shadow-lg ring-1 ring-rose sm:p-8\">\n        <h3 id=\"ship-title\" className=\"font-display text-3xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-2xl\">{t.formTitle}</h3>\n        <p className=\"mt-1 text-sm text-charcoal/70\">{t.formText}</p>\n\n        {added ? (\n          <div ref={doneRef} tabIndex={-1} role=\"status\" className=\"mt-6 rounded-xl bg-saffron/15 p-6 text-center focus:outline-none\">\n            <p className=\"font-display text-2xl font-semibold text-maroon\">✓ {t.added}</p>\n            {plan && <p className=\"mt-1 text-charcoal\">{txt(plan.name, locale)} · {rupees(plan.price)}</p>}\n            <div className=\"mx-auto mt-5 flex max-w-xs flex-col gap-3\">\n              <Link href={`/${locale}/cart?stream=donation`} className={btnPrimary}>{t.viewCart}</Link>\n              <button type=\"button\" onClick={() => { setAdded(false); setF((x) => ({ ...EMPTY, name: '', phone: x.phone })); }} className={btnGhost}>{t.another}</button>\n            </div>\n          </div>\n        ) : (\n          <form noValidate onSubmit={(e) => { e.preventDefault(); submit(false); }} className=\"mt-6\">\n            <div className=\"grid gap-5 sm:grid-cols-2\">\n              <Field id=\"m-name\" label={t.name} error={errors.name}>\n                <input id=\"m-name\" value={f.name} onChange={set('name')} autoComplete=\"name\" aria-invalid={!!errors.name} aria-describedby={errors.name ? 'm-name-e' : undefined} className={inputClass} />\n              </Field>\n              <Field id=\"m-phone\" label={t.phone} error={errors.phone}>\n                <input id=\"m-phone\" type=\"tel\" inputMode=\"tel\" value={f.phone} onChange={set('phone')} autoComplete=\"tel\" aria-invalid={!!errors.phone} aria-describedby={errors.phone ? 'm-phone-e' : undefined} className={inputClass} />\n              </Field>\n              <div className=\"sm:col-span-2\">\n                <Field id=\"m-address\" label={t.address} error={errors.address}>\n                  <textarea id=\"m-address\" rows={3} value={f.address} onChange={set('address')} autoComplete=\"street-address\" aria-invalid={!!errors.address} aria-describedby={errors.address ? 'm-address-e' : undefined} className={inputClass} />\n                </Field>\n              </div>\n              <Field id=\"m-district\" label={t.district} error={errors.district}>\n                <input id=\"m-district\" value={f.district} onChange={set('district')} autoComplete=\"address-level2\" aria-invalid={!!errors.district} aria-describedby={errors.district ? 'm-district-e' : undefined} className={inputClass} />\n              </Field>\n              <Field id=\"m-pin\" label={t.pin} error={errors.pin}>\n                <input id=\"m-pin\" inputMode=\"numeric\" maxLength={6} value={f.pin} onChange={set('pin')} autoComplete=\"postal-code\" aria-invalid={!!errors.pin} aria-describedby={errors.pin ? 'm-pin-e' : undefined} className={inputClass} />\n              </Field>\n            </div>\n\n            <label className=\"mt-6 flex cursor-pointer items-start gap-3 rounded-xl bg-rose/50 p-4\">\n              <input type=\"checkbox\" checked={f.renew} onChange={set('renew')} className=\"mt-1 h-5 w-5 shrink-0 accent-maroon\" />\n              <span>\n                <span className=\"block font-semibold text-charcoal\">{t.renew}</span>\n                <span className=\"block text-sm text-charcoal/70\">{t.renewHelp}</span>\n              </span>\n            </label>\n\n            <p className=\"mt-6 flex items-baseline justify-between border-t-2 border-rose pt-4\">\n              <span className=\"font-bold text-charcoal\">{t.totalLabel}</span>\n              <span className=\"font-display text-3xl font-semibold text-maroon\">{rupees(plan?.price ?? 0)}</span>\n            </p>\n            <div className=\"mt-5 grid gap-3 sm:grid-cols-2\">\n              <button type=\"submit\" className={btnPrimary}>{t.addToCart}</button>\n              <button type=\"button\" onClick={() => submit(true)} className={btnGhost}>{t.addAndGo}</button>\n            </div>\n            <p className=\"mt-4 text-sm text-charcoal/70\">{t.paymentNote}</p>\n          </form>\n        )}\n      </section>\n    </div>\n  );\n}\n\nfunction Field({ id, label, error, children }: { id: string; label: string; error?: string; children: React.ReactNode }) {\n  return (\n    <div>\n      <label htmlFor={id} className=\"mb-1 block text-sm font-bold text-charcoal\">{label} <span aria-hidden=\"true\" className=\"text-maroon\">*</span></label>\n      {children}\n      {error && <p id={`${id}-e`} role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{error}</p>}\n    </div>\n  );\n}\n","src/components/magazine/MagazineArchive.tsx":"'use client';\n\nimport { useState } from 'react';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { ISSUES, MONTHS_LONG } from '@/data/magazine';\nimport { txt } from '@/data/sevas';\n\ntype T = Dictionary['magazine'];\nconst YEARS = Array.from(new Set(ISSUES.map((i) => i.year))).sort((a, b) => b - a);\nconst btn = 'inline-flex flex-1 items-center justify-center rounded-md px-3 py-2 text-sm font-semibold transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-maroon';\n\n// Digital archive: year tabs and one card per issue. Buttons stay disabled until the ashram supplies a PDF or reader link.\nexport default function MagazineArchive({ locale, t }: { locale: Locale; t: T }) {\n  const [year, setYear] = useState(YEARS[0]);\n  const list = ISSUES.filter((i) => i.year === year).sort((a, b) => b.month - a.month);\n\n  return (\n    <div>\n      <div role=\"tablist\" aria-label={t.yearTabs} className=\"flex flex-wrap justify-center gap-2\">\n        {YEARS.map((y) => (\n          <button key={y} type=\"button\" role=\"tab\" id={`yr-${y}`} aria-selected={y === year} aria-controls=\"archive-panel\" onClick={() => setYear(y)}\n            className={`rounded-full px-5 py-2 font-semibold transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-maroon ${y === year ? 'bg-maroon text-white' : 'bg-white text-maroon ring-1 ring-rose hover:bg-rose'}`}>\n            {y}\n          </button>\n        ))}\n      </div>\n\n      <div id=\"archive-panel\" role=\"tabpanel\" aria-labelledby={`yr-${year}`} className=\"mt-8\">\n        {list.length === 0 ? (\n          <p className=\"text-center text-charcoal/70\">{t.archiveEmpty}</p>\n        ) : (\n          <ul className=\"grid gap-6 sm:grid-cols-2 lg:grid-cols-3\">\n            {list.map((i) => (\n              <li key={i.id} className=\"flex flex-col overflow-hidden rounded-2xl bg-white shadow ring-1 ring-rose\">\n                <div role=\"img\" aria-label={txt(i.title, locale)} className=\"relative aspect-[4/3] bg-maroon bg-cover bg-center\" style={{ backgroundImage: `url('${i.cover}')` }}>\n                  <span className=\"absolute left-3 top-3 rounded-full bg-charcoal/80 px-3 py-1 text-xs font-bold uppercase tracking-wider text-white [html[lang='ta']_&]:tracking-normal\">{MONTHS_LONG[locale][i.month - 1]} {i.year}</span>\n                </div>\n                <div className=\"flex flex-1 flex-col p-5\">\n                  <h3 className=\"font-display text-xl font-semibold leading-snug text-maroon [html[lang='ta']_&]:!leading-[1.35] [html[lang='ta']_&]:text-lg\">{txt(i.title, locale)}</h3>\n                  <p className=\"mt-2 flex-1 text-sm text-charcoal/80\">{txt(i.desc, locale)}</p>\n                  <div className=\"mt-4 flex gap-2\">\n                    {i.readUrl ? (\n                      <a href={i.readUrl} target=\"_blank\" rel=\"noopener noreferrer\" className={`${btn} bg-maroon text-white hover:bg-charcoal`}>{t.read}<span className=\"sr-only\"> ({t.newTab})</span></a>\n                    ) : (\n                      <span aria-disabled=\"true\" title={t.soon} className={`${btn} cursor-not-allowed bg-rose text-charcoal/50`}>{t.read}</span>\n                    )}\n                    {i.pdf ? (\n                      <a href={i.pdf} download className={`${btn} border-2 border-maroon text-maroon hover:bg-maroon hover:text-white`}>{t.download}</a>\n                    ) : (\n                      <span aria-disabled=\"true\" title={t.soon} className={`${btn} cursor-not-allowed border-2 border-rose text-charcoal/50`}>{t.download}</span>\n                    )}\n                  </div>\n                </div>\n              </li>\n            ))}\n          </ul>\n        )}\n        <p className=\"mt-6 text-center text-sm text-charcoal/70\">{t.archiveNote}</p>\n      </div>\n    </div>\n  );\n}\n","src/app/[locale]/magazine/page.tsx":"import type { Metadata } from 'next';\nimport Link from 'next/link';\nimport { notFound } from 'next/navigation';\nimport SubscribeSection from '@/components/magazine/SubscribeSection';\nimport MagazineArchive from '@/components/magazine/MagazineArchive';\nimport { getDictionary } from '@/lib/dictionary';\nimport { isLocale } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string }> };\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale } = await params;\n  if (!isLocale(locale)) return {};\n  const t = getDictionary(locale);\n  return {\n    title: `${t.magazine.meta.title} | ${t.site.name}`,\n    description: t.magazine.meta.description,\n  };\n}\n\n// Hero photo: apps/web/public/images/hero-bg.jpg\n// On desktop the photo fills the right two thirds of the banner, so Swamiji stays on the right and the text sits on the dark left side.\n// BG_POSITION decides which part of the photo is visible: first number = left/right (0% left edge, 100% right edge),\n// second number = up/down (0% top, 100% bottom). Raise the second number to show more of the lower part (Swamiji).\nconst BG_POSITION = '50% 70%';\n// On phones the photo fills the whole banner; this keeps Swamiji in the middle.\nconst BG_POSITION_MOBILE = '46% 65%';\n\nfunction Flame({ className = '' }: { className?: string }) {\n  return (\n    <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\" className={`shrink-0 ${className}`}>\n      <path d=\"M12 2c.6 3.2 4.5 5.4 4.5 10a4.5 4.5 0 0 1-9 0c0-2 .9-3.2 1.8-4.4.4 1.2 1 1.8 1.7 2C11.3 7.7 11.6 5 12 2z\" />\n    </svg>\n  );\n}\n\nfunction Arrow() {\n  return (\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\" className=\"transition-transform duration-300 group-hover:translate-x-1.5\">\n      <path d=\"M5 12h14M13 6l6 6-6 6\" />\n    </svg>\n  );\n}\n\nexport default async function MagazinePage({ params }: Params) {\n  const { locale } = await params;\n  if (!isLocale(locale)) notFound();\n  const dict = getDictionary(locale);\n  const t = dict.magazine;\n  const href = (p: string) => `/${locale}${p}`;\n\n  return (\n    <main>\n      {/* 1. Hero: the hero-bg.jpg photo as the background, with the title and buttons on the dark left side */}\n      <section aria-labelledby=\"mag-title\" className=\"relative isolate overflow-hidden bg-charcoal text-white\">\n        {/* Photo: whole banner on phones, right two thirds on desktop (the left side stays plain dark for the text) */}\n        <div aria-hidden=\"true\" className=\"absolute inset-0 -z-20 bg-cover bg-no-repeat lg:hidden\" style={{ backgroundImage: \"url('/images/hero-bg.jpg')\", backgroundPosition: BG_POSITION_MOBILE }} />\n        <div aria-hidden=\"true\" className=\"absolute inset-y-0 left-1/3 right-0 -z-20 hidden bg-cover bg-no-repeat lg:block\" style={{ backgroundImage: \"url('/images/hero-bg.jpg')\", backgroundPosition: BG_POSITION }} />\n\n        {/* Readability layers. Phones: the whole photo is darkened. Desktop: the photo fades into the dark left side. */}\n        <div aria-hidden=\"true\" className=\"absolute inset-0 -z-10 bg-charcoal/65 lg:hidden\" />\n        <div aria-hidden=\"true\" className=\"absolute inset-0 -z-10 hidden bg-gradient-to-r from-charcoal from-33% via-charcoal/60 via-50% to-charcoal/0 to-75% lg:block\" />\n        <div aria-hidden=\"true\" className=\"absolute inset-0 -z-10 bg-gradient-to-t from-charcoal/50 via-transparent to-charcoal/30\" />\n\n        <nav aria-label={t.crumbLabel} className=\"mx-auto max-w-7xl px-4 pt-6 text-sm text-white/80 lg:px-8\">\n          <ol className=\"flex flex-wrap items-center gap-2\">\n            <li><Link href={href('')} className=\"underline-offset-4 hover:text-white hover:underline\">{dict.nav.home}</Link></li>\n            <li aria-hidden=\"true\">/</li>\n            <li aria-current=\"page\" className=\"font-semibold text-white\">{dict.nav.magazine}</li>\n          </ol>\n        </nav>\n\n        <div className=\"mx-auto flex max-w-7xl items-center px-4 pb-24 pt-10 sm:pb-28 lg:min-h-[520px] lg:px-8 lg:pb-32\">\n          <div className=\"mx-auto w-full min-w-0 max-w-2xl text-center lg:mx-0 lg:max-w-[40rem] lg:text-left\">\n            <p className=\"inline-flex max-w-full items-center gap-2 rounded-full border border-saffron/70 bg-charcoal/50 px-4 py-1.5 text-sm font-semibold text-white backdrop-blur-sm sm:text-base\">\n              <Flame className=\"text-saffron\" />\n              <span>{t.eyebrow}</span>\n            </p>\n            <h1 id=\"mag-title\" className=\"animate-fade-up mt-5 font-display text-5xl font-semibold leading-[1.1] !text-white drop-shadow-[0_2px_14px_rgba(0,0,0,0.6)] motion-reduce:animate-none sm:text-6xl lg:text-7xl [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-4xl [html[lang='ta']_&]:sm:text-5xl [html[lang='ta']_&]:lg:text-6xl\">{t.title}</h1>\n            <div aria-hidden=\"true\" className=\"mt-4 flex items-center justify-center gap-3 lg:justify-start\">\n              <span className=\"h-px w-14 bg-saffron\" />\n              <span className=\"h-2 w-2 rotate-45 bg-saffron\" />\n              <span className=\"h-px w-14 bg-saffron\" />\n            </div>\n            <p className=\"mt-5 font-serif text-lg leading-relaxed text-white/95 drop-shadow-[0_1px_8px_rgba(0,0,0,0.6)] sm:text-xl\">{t.intro}</p>\n\n            <div className=\"mt-8 flex flex-wrap justify-center gap-3 lg:justify-start\">\n              <a href=\"#subscribe-form\" className=\"group inline-flex items-center gap-2 rounded-full bg-saffron px-6 py-2.5 font-semibold text-charcoal transition-colors hover:bg-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white\">\n                {t.subscribeCta}\n                <Arrow />\n              </a>\n              <a href=\"#archive\" className=\"inline-flex items-center rounded-full border-2 border-white/70 px-6 py-2.5 font-semibold text-white transition-colors hover:bg-white hover:text-maroon focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white\">\n                {t.archiveCta}\n              </a>\n            </div>\n          </div>\n        </div>\n\n        {/* Soft wave into the white section below */}\n        <svg aria-hidden=\"true\" viewBox=\"0 0 1440 40\" preserveAspectRatio=\"none\" className=\"absolute inset-x-0 bottom-0 h-8 w-full text-white sm:h-10\">\n          <path d=\"M0 40V18C240 -2 480 -2 720 14S1200 34 1440 12V40Z\" fill=\"currentColor\" />\n        </svg>\n      </section>\n\n      {/* 2. Plans and shipping form */}\n      <section aria-label={t.plansTitle} className=\"bg-white pb-16 pt-6 sm:pb-20\">\n        <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n          <SubscribeSection locale={locale} t={t} />\n        </div>\n      </section>\n\n      {/* 3. Digital archive */}\n      <section id=\"archive\" aria-labelledby=\"archive-title\" className=\"scroll-mt-20 bg-rose/50 py-12 sm:py-16\">\n        <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n          <div className=\"text-center\">\n            <h2 id=\"archive-title\" className=\"font-display text-3xl font-semibold text-maroon sm:text-4xl [html[lang='ta']_&]:!leading-[1.3]\">{t.archiveTitle}</h2>\n            <div aria-hidden=\"true\" className=\"mt-3 flex items-center justify-center gap-3\"><span className=\"h-px w-12 bg-saffron\" /><span className=\"h-2 w-2 rotate-45 bg-saffron\" /><span className=\"h-px w-12 bg-saffron\" /></div>\n            <p className=\"mt-3 text-charcoal/80\">{t.archiveText}</p>\n          </div>\n          <div className=\"mt-8\"><MagazineArchive locale={locale} t={t} /></div>\n        </div>\n      </section>\n\n      {/* 4. Help */}\n      <section aria-labelledby=\"help-title\" className=\"bg-saffron py-10 text-charcoal sm:py-12\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-6 px-4 text-center lg:flex-row lg:justify-between lg:px-8 lg:text-left\">\n          <div className=\"max-w-2xl\">\n            <h2 id=\"help-title\" className=\"font-display text-3xl font-semibold leading-tight !text-charcoal sm:text-4xl\">{t.helpTitle}</h2>\n            <p className=\"mt-2 text-lg\">{t.helpText}</p>\n          </div>\n          <Link\n            href={href('/contact')}\n            className=\"group inline-flex items-center gap-2 rounded-md bg-charcoal px-7 py-3 font-semibold text-white transition-colors hover:bg-maroon focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-charcoal\"\n          >\n            {t.helpCta}\n            <Arrow />\n          </Link>\n        </div>\n      </section>\n    </main>\n  );\n}\n"};
const DICT = {"en":{"magazine":{"meta":{"title":"Magazine","description":"Subscribe to the Vedaneri magazine and read past issues."},"crumbLabel":"Breadcrumb","eyebrow":"Monthly spiritual magazine","title":"Vedaneri Magazine","intro":"Swamiji's teachings, Vedanta, Thirukkural and Thayumanavar, delivered to your home each month. Subscribe for a year or more, or read past issues online.","subscribeCta":"Subscribe","archiveCta":"Read past issues","plansTitle":"Physical Print Subscription","plansText":"Choose a plan. The magazine is posted to your address.","issues":"issues","perPlan":"for the plan","bestValue":"Best value","selected":"Selected","choose":"Choose this plan","perIssue":"{n} per issue","planNote":"Plan prices are from the ashram. Language editions and postage are to be confirmed.","formTitle":"Subscriber Shipping Details","formText":"Where should we post your copy?","name":"Full name","phone":"Mobile number","address":"Delivery address","district":"City / District","pin":"PIN code","renew":"Renew automatically when the plan ends","renewHelp":"We will remind you before renewing. You can cancel any time.","errPlan":"Please choose a plan.","errName":"Please enter your name.","errPhone":"Enter a 10-digit mobile number.","errAddress":"Please enter the delivery address.","errDistrict":"Please enter the city or district.","errPin":"Enter a 6-digit PIN code.","totalLabel":"Total","addToCart":"Add subscription to cart","addAndGo":"Add and go to cart","added":"Added to your cart","viewCart":"View cart","another":"Subscribe for someone else","paymentNote":"Subscriptions are paid like donations, in your cart. Online payment is not connected yet (demo).","archiveTitle":"Digital Archive","archiveText":"Read or download past issues.","yearTabs":"Year","read":"Read Online","download":"Download PDF","soon":"Coming soon","archiveEmpty":"No issues for this year yet.","archiveNote":"These issues are samples. The ashram will upload the real back issues.","newTab":"opens in a new tab","helpTitle":"Questions about your subscription?","helpText":"Write to us for address changes, missing copies or bulk orders.","helpCta":"Contact us"},"shop":{"subscriberLabel":"Subscriber","shipLabel":"Deliver to","renewLabel":"Auto-renewal","yes":"Yes","no":"No"}},"ta":{"magazine":{"meta":{"title":"இதழ்","description":"வேதநெறி இதழுக்குச் சந்தா செலுத்துங்கள்; பழைய இதழ்களைப் படியுங்கள்."},"crumbLabel":"பாதை","eyebrow":"மாதாந்திர ஆன்மிக இதழ்","title":"வேதநெறி இதழ்","intro":"ஸ்வாமிஜியின் உபதேசங்கள், வேதாந்தம், திருக்குறள், தாயுமானவர் — ஒவ்வொரு மாதமும் உங்கள் இல்லம் தேடி வரும். ஓராண்டு அல்லது அதற்கு மேல் சந்தா செலுத்தலாம்; பழைய இதழ்களை இணையத்திலும் படிக்கலாம்.","subscribeCta":"சந்தா செலுத்த","archiveCta":"பழைய இதழ்கள்","plansTitle":"அச்சு இதழ் சந்தா","plansText":"ஒரு திட்டத்தைத் தேர்ந்தெடுங்கள். இதழ் உங்கள் முகவரிக்கு அஞ்சலில் வரும்.","issues":"இதழ்கள்","perPlan":"முழுத் திட்டத்திற்கு","bestValue":"சிறந்த தேர்வு","selected":"தேர்ந்தெடுக்கப்பட்டது","choose":"இதைத் தேர்ந்தெடு","perIssue":"ஒரு இதழ் {n}","planNote":"திட்டக் கட்டணங்கள் ஆசிரமத்தின்படி. மொழிப் பதிப்பு, அஞ்சல் கட்டணம் உறுதி செய்யப்பட வேண்டும்.","formTitle":"சந்தாதாரர் முகவரி விவரம்","formText":"இதழை எங்கு அனுப்ப வேண்டும்?","name":"முழுப் பெயர்","phone":"கைபேசி எண்","address":"முகவரி","district":"நகரம் / மாவட்டம்","pin":"அஞ்சல் குறியீடு","renew":"திட்டம் முடிந்ததும் தானாகப் புதுப்பிக்க","renewHelp":"புதுப்பிக்கும் முன் நினைவூட்டுவோம். எப்போது வேண்டுமானாலும் நிறுத்தலாம்.","errPlan":"ஒரு திட்டத்தைத் தேர்ந்தெடுங்கள்.","errName":"பெயரை உள்ளிடுங்கள்.","errPhone":"10 இலக்க கைபேசி எண்ணை உள்ளிடுங்கள்.","errAddress":"முகவரியை உள்ளிடுங்கள்.","errDistrict":"நகரம் / மாவட்டத்தை உள்ளிடுங்கள்.","errPin":"6 இலக்க அஞ்சல் குறியீட்டை உள்ளிடுங்கள்.","totalLabel":"மொத்தம்","addToCart":"சந்தாவை கூடையில் சேர்","addAndGo":"சேர்த்து கூடைக்குச் செல்","added":"கூடையில் சேர்க்கப்பட்டது","viewCart":"கூடையைப் பார்","another":"வேறொருவருக்குச் சந்தா","paymentNote":"சந்தா, நன்கொடை போலவே கூடையில் செலுத்தப்படும். இணையவழிப் பணம் செலுத்துதல் இன்னும் இணைக்கப்படவில்லை (மாதிரி).","archiveTitle":"மின்னிதழ் காப்பகம்","archiveText":"பழைய இதழ்களைப் படிக்கலாம்; பதிவிறக்கலாம்.","yearTabs":"ஆண்டு","read":"இணையத்தில் படிக்க","download":"PDF பதிவிறக்கம்","soon":"விரைவில்","archiveEmpty":"இந்த ஆண்டிற்கான இதழ்கள் இல்லை.","archiveNote":"இவை மாதிரி இதழ்கள். ஆசிரமம் உண்மையான பழைய இதழ்களைப் பதிவேற்றும்.","newTab":"புதிய தாவலில் திறக்கும்","helpTitle":"சந்தா குறித்த கேள்விகளா?","helpText":"முகவரி மாற்றம், வராத இதழ்கள், அதிக எண்ணிக்கை ஆர்டர்களுக்கு எங்களை அணுகுங்கள்.","helpCta":"தொடர்புகொள்ள"},"shop":{"subscriberLabel":"சந்தாதாரர்","shipLabel":"அனுப்ப வேண்டிய முகவரி","renewLabel":"தானியங்கு புதுப்பிப்பு","yes":"ஆம்","no":"இல்லை"}}};
const backup = (p) => { if (fs.existsSync(p) && !fs.existsSync(p + '.bak')) fs.copyFileSync(p, p + '.bak'); };
for (const [rel, content] of Object.entries(FILES)) {
  const p = path.join(root, ...rel.split('/'));
  fs.mkdirSync(path.dirname(p), { recursive: true });
  backup(p);
  fs.writeFileSync(p, content, 'utf8');
  console.log('wrote   ' + rel);
}
for (const lang of ['en', 'ta']) {
  const p = path.join(root, 'src', 'dictionaries', lang + '.json');
  backup(p);
  const d = JSON.parse(fs.readFileSync(p, 'utf8'));
  d.magazine = DICT[lang].magazine;
  Object.assign(d.shop, DICT[lang].shop);
  fs.writeFileSync(p, JSON.stringify(d, null, 2) + '\n', 'utf8');
  console.log('merged  src/dictionaries/' + lang + '.json');
}
console.log('\nDone. Now: stop the dev server, delete the .next folder, run npm run dev, then open /en/magazine');
